'use strict'; const EVENTS_API_URL = 'https://events.mrwrite.co.za/api/public/events/mr-write/main-calendar'; document.addEventListener('DOMContentLoaded', () => { initNavbarScroll(); initSmoothScroll(); initTeaOMeter(); initScrollAnimations(); initBackToTop(); setCurrentYear(); initDynamicEvents(); initShopHours(); initDynamicGallery(); }); function initNavbarScroll() { const navbar = document.getElementById('mainNav'); if (!navbar) return; const SCROLL_THRESHOLD = 60; const updateNavbar = () => { if (window.scrollY > SCROLL_THRESHOLD) { navbar.classList.add('scrolled'); } else { navbar.classList.remove('scrolled'); } }; updateNavbar(); window.addEventListener('scroll', updateNavbar, { passive: true }); } function initSmoothScroll() { const navLinks = document.querySelectorAll('.nav-link'); const sections = document.querySelectorAll('section[id]'); navLinks.forEach(link => { link.addEventListener('click', (e) => { const href = link.getAttribute('href'); if (!href.startsWith('#')) return; e.preventDefault(); const target = document.querySelector(href); if (target) { target.scrollIntoView({ behavior: 'smooth' }); } const navCollapse = document.getElementById('navbarContent'); if (navCollapse?.classList.contains('show')) { const bsCollapse = bootstrap.Collapse.getInstance(navCollapse); bsCollapse?.hide(); } }); }); const highlightActive = () => { const scrollPos = window.scrollY + 120; sections.forEach(section => { const top = section.offsetTop; const height = section.offsetHeight; const id = section.getAttribute('id'); if (scrollPos >= top && scrollPos < top + height) { navLinks.forEach(link => { link.classList.remove('active'); if (link.getAttribute('href') === `#${id}`) { link.classList.add('active'); } }); } }); }; window.addEventListener('scroll', highlightActive, { passive: true }); highlightActive(); } function initTeaOMeter() { const moodButtons = document.querySelectorAll('.mood-btn'); const moodSelector = document.getElementById('moodSelector'); const teaResult = document.getElementById('teaResult'); const resultEmoji = document.getElementById('resultEmoji'); const resultName = document.getElementById('resultName'); const resultDesc = document.getElementById('resultDesc'); const tryAgainBtn = document.getElementById('tryAgainBtn'); if (!moodSelector || !teaResult) return; const teaRecommendations = { happy: [ { emoji: '🌸', name: 'Jasmine Green Tea', desc: 'Light, floral, and sunshine in a cup — just like your mood! Perfect for keeping those good vibes going.' }, { emoji: '🍑', name: 'Peach Oolong', desc: 'Sweet, fruity, and smooth — a tea that matches your sunny disposition perfectly.' } ], stressed: [ { emoji: '🌿', name: 'Chamomile & Lavender', desc: 'Take a deep breath. This gentle herbal blend is like a warm hug for your nerves. You\'ve got this.' }, { emoji: '🫖', name: 'Peppermint Rooibos', desc: 'Caffeine-free and cooling — let the tension melt away with every sip. The ocean is right outside.' } ], sleepy: [ { emoji: '⚡', name: 'English Breakfast (Strong!)', desc: 'Rise and shine! This bold, malty classic will get your engine running. Two sugars? Go wild.' }, { emoji: '🍵', name: 'Yerba Maté Boost', desc: 'Nature\'s energy drink. Smooth, earthy, and packed with the pick-me-up you need right now.' } ], adventurous: [ { emoji: '🌶️', name: 'Chai Masala (Spicy!)', desc: 'Bold spices, warm ginger, a kick of pepper — this brew matches your daring spirit. Fortune favours the spiced!' }, { emoji: '🫧', name: 'Butterfly Pea Flower Tea', desc: 'Starts blue, add lemon and watch it turn purple! As wild and wonderful as your adventurous soul.' } ], cozy: [ { emoji: '🍫', name: 'Chocolate Rooibos', desc: 'Rich, creamy, and caffeine-free — like wrapping yourself in a warm blanket on a rainy Hermanus day.' }, { emoji: '🍯', name: 'Honeybush & Vanilla', desc: 'Sweet, mellow, and uniquely South African. The perfect companion for a good book and a comfy chair.' } ], fancy: [ { emoji: '🫅', name: 'Earl Grey Supreme', desc: 'Bergamot-kissed, elegant, and refined — pinky up, darling. You deserve nothing less than the finest.' }, { emoji: '🌹', name: 'Rose Petal Darjeeling', desc: 'The "Champagne of Teas" meets delicate rose petals. Exquisite, just like your taste.' } ] }; moodButtons.forEach(btn => { btn.addEventListener('click', () => { const mood = btn.dataset.mood; const options = teaRecommendations[mood]; if (!options) return; const tea = options[Math.floor(Math.random() * options.length)]; resultEmoji.textContent = tea.emoji; resultName.textContent = tea.name; resultDesc.textContent = tea.desc; moodSelector.style.display = 'none'; teaResult.classList.add('show'); }); }); tryAgainBtn?.addEventListener('click', () => { teaResult.classList.remove('show'); moodSelector.style.display = 'block'; }); } function initScrollAnimations() { const sections = document.querySelectorAll( '.section-about, .section-events, .section-teaometer, .section-gallery, .section-contact, .section-booking' ); sections.forEach(section => { section.classList.add('fade-in-section'); }); const observer = new IntersectionObserver( (entries) => { entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target); } }); }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' } ); sections.forEach(section => observer.observe(section)); } function initBackToTop() { const btn = document.getElementById('backToTop'); if (!btn) return; const SHOW_THRESHOLD = 400; window.addEventListener('scroll', () => { if (window.scrollY > SHOW_THRESHOLD) { btn.classList.add('visible'); } else { btn.classList.remove('visible'); } }, { passive: true }); btn.addEventListener('click', () => { window.scrollTo({ top: 0, behavior: 'smooth' }); }); } function setCurrentYear() { const yearEl = document.getElementById('currentYear'); if (yearEl) { yearEl.textContent = new Date().getFullYear(); } } function initDynamicEvents() { const carouselEl = document.getElementById('eventsCarousel'); const trackEl = document.getElementById('eventsTrack'); const indicatorsEl = document.getElementById('eventsIndicators'); const prevBtn = document.getElementById('eventsPrev'); const nextBtn = document.getElementById('eventsNext'); const errorEl = document.getElementById('eventsError'); if (!trackEl || !indicatorsEl) return; const MONTHS = ['JAN','FEB','MAR','APR','MAY','JUN', 'JUL','AUG','SEP','OCT','NOV','DEC']; function parseDate(dateStr) { const [y, m, d] = dateStr.split('-').map(Number); return new Date(y, m - 1, d); } function buildEventCard(evt) { const d = parseDate(evt.date); const dayNum = String(d.getDate()).padStart(2, '0'); const month = MONTHS[d.getMonth()]; const dayName = evt.day || d.toLocaleDateString('en-US', { weekday: 'short' }).toUpperCase(); const iconClass = evt.icon || 'bi-calendar-event'; let calendarHref = evt.calendarLink || ''; if (calendarHref && evt.description) { try { const url = new URL(calendarHref); if (!url.searchParams.has('details') && !url.searchParams.has('description') && !url.searchParams.has('text')) { url.searchParams.append('details', evt.description); } calendarHref = url.toString(); } catch (e) { calendarHref = `${calendarHref}${calendarHref.includes('?') ? '&' : '?'}details=${encodeURIComponent(evt.description)}`; } } return ` <div class="event-card"> <div class="event-card-icon"><i class="bi ${iconClass}"></i></div> <div class="event-card-date"> <span class="event-day">${dayName}</span> <span class="event-num">${dayNum}</span> <span class="event-month">${month}</span> </div> <h3 class="event-card-title">${evt.title}</h3> <p class="event-card-desc">${evt.description}</p> <span class="event-card-time"><i class="bi bi-clock"></i> ${evt.time}</span> ${calendarHref ? `<a href="${calendarHref}" target="_blank" rel="noopener noreferrer" class="btn btn-calendar"><i class="bi bi-calendar-plus"></i> Add to Calendar</a>` : ''} </div>`; } function showError() { if (carouselEl) carouselEl.style.display = 'none'; if (errorEl) errorEl.style.display = 'block'; } let events = []; let currentIndex = 0; let autoplayTimer = null; function updatePositions() { const cards = trackEl.querySelectorAll('.peek-card'); const total = cards.length; if (total === 0) return; cards.forEach((card, i) => { card.classList.remove('peek-left', 'peek-active', 'peek-right', 'peek-hidden'); if (i === currentIndex) { card.classList.add('peek-active'); } else if (i === (currentIndex - 1 + total) % total) { card.classList.add('peek-left'); } else if (i === (currentIndex + 1) % total) { card.classList.add('peek-right'); } else { card.classList.add('peek-hidden'); } }); const dots = indicatorsEl.querySelectorAll('.peek-dot'); dots.forEach((dot, i) => { dot.classList.toggle('active', i === currentIndex); }); } function goTo(index) { const total = events.length; currentIndex = ((index % total) + total) % total; updatePositions(); resetAutoplay(); } function goNext() { goTo(currentIndex + 1); } function goPrev() { goTo(currentIndex - 1); } function resetAutoplay() { clearInterval(autoplayTimer); autoplayTimer = setInterval(goNext, 5000); } fetch(EVENTS_API_URL) .then(res => { if (!res.ok) throw new Error(`HTTP ${res.status}`); return res.json(); }) .then(data => { const today = new Date(); today.setHours(0, 0, 0, 0); const upcoming = data.filter(evt => parseDate(evt.date) >= today); if (upcoming.length === 0) { showError(); return; } upcoming.sort((a, b) => parseDate(a.date) - parseDate(b.date)); events = upcoming; trackEl.innerHTML = upcoming .map((evt, i) => { const posClass = i === 0 ? 'peek-active' : i === upcoming.length - 1 && upcoming.length > 2 ? 'peek-left' : i === 1 ? 'peek-right' : 'peek-hidden'; return `<div class="peek-card ${posClass}">${buildEventCard(evt)}</div>`; }) .join(''); indicatorsEl.innerHTML = upcoming .map((_, i) => `<button class="peek-dot${i === 0 ? ' active' : ''}" aria-label="Event ${i + 1}"></button>` ) .join(''); indicatorsEl.querySelectorAll('.peek-dot').forEach((dot, i) => { dot.addEventListener('click', () => goTo(i)); }); if (prevBtn) prevBtn.addEventListener('click', goPrev); if (nextBtn) nextBtn.addEventListener('click', goNext); if (upcoming.length <= 1) { if (prevBtn) prevBtn.style.display = 'none'; if (nextBtn) nextBtn.style.display = 'none'; } resetAutoplay(); if (carouselEl) { carouselEl.addEventListener('mouseenter', () => clearInterval(autoplayTimer)); carouselEl.addEventListener('mouseleave', resetAutoplay); } }) .catch(() => showError()); } function loadShopHours() { if (!loadShopHours._promise) { loadShopHours._promise = fetch('data/hours.json') .then(res => { if (!res.ok) throw new Error(`HTTP ${res.status}`); return res.json(); }); } return loadShopHours._promise; } function initShopHours() { loadShopHours() .then(data => { const hours = data.hours; const tradingEl = document.getElementById('tradingHours'); if (tradingEl) { tradingEl.innerHTML = hours.map(h => { if (h.label) return `${h.days}: ${h.label}`; return `${h.days}: ${h.open} \u2013 ${h.close}`; }).join('<br/>'); } const bookingEl = document.getElementById('bookingHours'); if (bookingEl) { bookingEl.innerHTML = hours.map(h => { if (h.label) return `${h.days} ${h.label}`; return `${h.days} ${h.open} \u2013 ${h.close}`; }).join(' &bull; '); } window.dispatchEvent(new CustomEvent('shopHoursLoaded', { detail: data })); }) .catch(() => { const tradingEl = document.getElementById('tradingHours'); if (tradingEl) { tradingEl.innerHTML = 'Mon \u2013 Fri: 7:30 \u2013 16:30<br/>Sat: 7:30 \u2013 15:00<br/>Sun: Closed'; } const bookingEl = document.getElementById('bookingHours'); if (bookingEl) { bookingEl.textContent = 'Mon\u2013Fri 7:30 \u2013 16:30 \u2022 Sat 7:30 \u2013 15:00 \u2022 Sun Closed'; } window.dispatchEvent(new CustomEvent('shopHoursLoaded', { detail: null })); }); } const galleryState = { images: [], currentIndex: 0 }; const TILT_CLASSES = ['tilt-1', 'tilt-2', 'tilt-3', 'tilt-4', 'tilt-5', 'tilt-6']; function initDynamicGallery() { const gridEl = document.getElementById('galleryGrid'); const errorEl = document.getElementById('galleryError'); if (!gridEl) return; fetch('data/gallery.json') .then(res => { if (!res.ok) throw new Error(`HTTP ${res.status}`); return res.json(); }) .then(data => { const categories = data.categories; if (!categories || categories.length === 0) { showGalleryError(gridEl, errorEl); return; } gridEl.innerHTML = categories.map((cat, idx) => { return buildCategoryCard(cat, idx); }).join(''); attachGalleryClicks(categories); loadThumbnails(categories); }) .catch(() => showGalleryError(gridEl, errorEl)); initLightboxNav(); } function buildCategoryCard(cat, idx) { const tiltClass = TILT_CLASSES[idx % TILT_CLASSES.length]; const hasLink = !!cat.link; const imageCount = cat.images ? cat.images.length : 0; const iconColor = isLightColor(cat.color) ? 'rgba(0,0,0,0.15)' : 'rgba(255,255,255,0.4)'; return ` <div class="col-sm-6 col-lg-4"> <div class="gallery-card ${tiltClass}" data-category-id="${cat.id}" ${hasLink ? `data-external-link="${cat.link}"` : ''} role="button" tabindex="0" aria-label="${hasLink ? 'Visit ' + cat.title : 'View ' + cat.title + ' photos'}"> <div class="gallery-card-img" id="thumb-${cat.id}" style="background-color: ${cat.color};"> <i class="bi ${cat.icon} gallery-placeholder-icon" style="color: ${iconColor};"></i> ${hasLink ? '<span class="gallery-link-badge"><i class="bi bi-box-arrow-up-right"></i> Visit</span>' : ''} ${imageCount > 1 ? `<span class="gallery-count-badge"><i class="bi bi-images"></i> ${imageCount}</span>` : ''} </div> <div class="gallery-card-body"> <h5>${cat.title}</h5> <p>${cat.subtitle}</p> </div> </div> </div>`; } function loadThumbnails(categories) { categories.forEach(cat => { if (!cat.images || cat.images.length === 0) return; const randomImg = cat.images[Math.floor(Math.random() * cat.images.length)]; const thumbEl = document.getElementById(`thumb-${cat.id}`); if (!thumbEl) return; const img = new Image(); img.onload = () => { const imgEl = document.createElement('img'); imgEl.src = randomImg.src; imgEl.alt = randomImg.alt || ''; imgEl.loading = 'lazy'; thumbEl.innerHTML = ''; thumbEl.appendChild(imgEl); const card = thumbEl.closest('.gallery-card'); if (card?.dataset.externalLink) { thumbEl.insertAdjacentHTML('beforeend', '<span class="gallery-link-badge"><i class="bi bi-box-arrow-up-right"></i> Visit</span>'); } if (cat.images.length > 1) { thumbEl.insertAdjacentHTML('beforeend', `<span class="gallery-count-badge"><i class="bi bi-images"></i> ${cat.images.length}</span>`); } }; img.src = randomImg.src; }); } function attachGalleryClicks(categories) { document.querySelectorAll('.gallery-card').forEach(card => { card.addEventListener('click', () => { const externalLink = card.dataset.externalLink; if (externalLink) { window.open(externalLink, '_blank', 'noopener,noreferrer'); return; } const catId = card.dataset.categoryId; const cat = categories.find(c => c.id === catId); if (!cat || !cat.images || cat.images.length === 0) return; galleryState.images = cat.images; galleryState.currentIndex = 0; openLightbox(0); }); card.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); card.click(); } }); }); } function openLightbox(index) { const images = galleryState.images; if (!images || images.length === 0) return; galleryState.currentIndex = index; const img = images[index]; const lightboxImg = document.getElementById('lightboxImg'); const lightboxCaption = document.getElementById('lightboxCaption'); const lightboxCounter = document.getElementById('lightboxCounter'); const prevBtn = document.getElementById('lightboxPrev'); const nextBtn = document.getElementById('lightboxNext'); if (lightboxImg) { lightboxImg.src = img.src; lightboxImg.alt = img.alt; } if (lightboxCaption) { lightboxCaption.textContent = img.caption; } const hasMultiple = images.length > 1; if (prevBtn) prevBtn.style.display = hasMultiple ? 'flex' : 'none'; if (nextBtn) nextBtn.style.display = hasMultiple ? 'flex' : 'none'; if (lightboxCounter) { lightboxCounter.style.display = hasMultiple ? 'block' : 'none'; lightboxCounter.textContent = `${index + 1} / ${images.length}`; } const modalEl = document.getElementById('galleryLightbox'); if (modalEl && typeof bootstrap !== 'undefined') { const modal = bootstrap.Modal.getOrCreateInstance(modalEl); modal.show(); } } function initLightboxNav() { const prevBtn = document.getElementById('lightboxPrev'); const nextBtn = document.getElementById('lightboxNext'); if (prevBtn) { prevBtn.addEventListener('click', (e) => { e.stopPropagation(); const images = galleryState.images; const newIndex = (galleryState.currentIndex - 1 + images.length) % images.length; openLightbox(newIndex); }); } if (nextBtn) { nextBtn.addEventListener('click', (e) => { e.stopPropagation(); const images = galleryState.images; const newIndex = (galleryState.currentIndex + 1) % images.length; openLightbox(newIndex); }); } document.addEventListener('keydown', (e) => { const modalEl = document.getElementById('galleryLightbox'); if (!modalEl || !modalEl.classList.contains('show')) return; if (e.key === 'ArrowLeft') { prevBtn?.click(); } else if (e.key === 'ArrowRight') { nextBtn?.click(); } }); } function showGalleryError(gridEl, errorEl) { if (gridEl) gridEl.style.display = 'none'; if (errorEl) errorEl.style.display = 'block'; } function isLightColor(hex) { const c = hex.replace('#', ''); const r = parseInt(c.substring(0, 2), 16); const g = parseInt(c.substring(2, 4), 16); const b = parseInt(c.substring(4, 6), 16); return (r * 0.299 + g * 0.587 + b * 0.114) > 160; }